INSERT OR REPLACE INTO marketplace_listings (row_id, channel_name, price, url, matched_title, size, seller, confidence, available) VALUES (17, 'Daraz', 1088.0, 'https://www.daraz.com.bd/products/biocare-acne-oil-pores-minimizing-serum-i495824760.html', 'BioCare Acne, Oil & Pores Minimizing Serum', 'BioCare Acne, Oil & Pores Minimizing Serum Active ingredients : Salicylic Acid Mandelic Acid Azelaic Acid Niacinamide Perfect Solution for Acne, excessive oil & enlarged poresBio Care Acne, Oil & Pores Minimizing Serum is a lightweight & non-greasy formula designed to reduce acne, control excess oil, and minimize the appearance of pores. Enriched with salicylic acid, azelaic acid, and niacinamide, it helps to unclog pores, soothe inflammation, and improve skin texture for a clearer, balanced complexion.BenefitReduces AcneControls OilMinimizes PoresFeatureLightweightEasy to useFast absorbingNon-greasyBio Care Acne, Oil & Pores Minimizing Serum is a powerful solution for oily and acne-prone skin, formulated to reduce breakouts and refine texture. Formulated with salicylic acid, it clears clogged pores by dissolving excess sebum and impurities. Azelaic acid soothes inflammation, minimizes redness, and gently exfoliates for smoother skin. Niacinamide helps regulate oil production, tightens enlarged pores, and strengthens the skin barrier. This lightweight serum absorbs quickly, making it perfect for daily use without causing dryness or irritation. With consistent application, it leaves the skin balanced, clear, and visibly healthier.How to use: Apply 2-3 drops at night to the affected area after cleansing and dry face. Recommend to use sun protection at day time.Volume: 30 ml', 'Bio-Xin Cosmeceuticals', 100.0, 1);
