INSERT OR REPLACE INTO marketplace_listings (row_id, channel_name, price, url, matched_title, size, seller, confidence, available) VALUES (18, 'Daraz', 1088.0, 'https://www.daraz.com.bd/products/biocare-acne-oil-control-moisturizing-gel-i495881095.html', 'BioCare Acne Oil Control Moisturizing Gel', 'BioCare Acne Oil Control Moisturizing Gel Active ingredients : Salicylic Acid Green Tea Extract Licorice Extract Expert Solution for Acne & Oil ControlBio Care Acne Oil Control Moisturizing Gel helps reduce acne and control excess oil for clear skin. It soothes redness with Green Tea Extract and fades acne marks with Licorice and Niacinamide. This lightweight gel hydrates without clogging pores, leaving skin smooth and refreshed. Perfect for oily and acne-prone skin.BenefitReduces AcneControls OilMinimizes PoresFeatureMoisturizingLight weightNon-GreasyBio Care Acne Oil Control Moisturizing Gel is a lightweight, non-greasy formula specially designed for acne-prone and oily skin. Enriched with niacinamide, it helps regulate excess oil, minimize pores, and soothe irritation while strengthening the skin barrier. Green tea extract reduces inflammation and calm redness for a balanced complexion. Licorice extract brightens the skin and reduces the appearance of acne spots, promoting an even tone. This gel hydrates without clogging pores, leaving your skin refreshed, smooth, and shine-free. Perfect for daily use, it helps maintain healthy, clear skin while addressing acne and oil control needs.How to use:  Apply a sufficient amount of moisturizer on clean & dry skin. Gently massage in circular motions. Use twice daily, and follow with sun protection during the day.Volume: 50 ml', 'Bio-Xin Cosmeceuticals', 100.0, 1);
