INSERT OR REPLACE INTO marketplace_listings (row_id, channel_name, price, url, matched_title, size, seller, confidence, available) VALUES (19, 'Daraz', 1099.0, 'https://www.daraz.com.bd/products/biocare-brightening-aloe-vera-gel-i513183535.html', 'BioCare Brightening Aloe Vera Gel', 'BioCare Brightening Aloe Vera Gel Active ingredients : Aloe Vera Kojic acid Vitamin E Glycerin Brighten, hydrate, and heal your skin naturally with soothing Aloe Vera for a radiant, glowing lookExperience a lightweight hydrating formula with Aloe Vera extract that brightens, heals, and soothes the skin. Kojic Acid reduces dark spots and evens skin tone, while Vitamin E repairs sun damage. Glycerin locks in moisture, leaving your skin soft and radiant. Suitable for all skin types, this gel is your perfect solution for dryness, dullness, spots, and sun damage!BenefitBrighteningHydratingSoothing and HealingFades spots and evens the skin toneRepairs sun damageFeatureSuitable for all types of skinFast absorbingLight-weightRefreshingNon-comedogenicBio Care Brightening Aloevera Gel is a refreshing, skin-loving gel that hydrates, brightens, repairs your skin. Crafted with Aloe Vera, it offers powerful moisturizing, soothing, and healing effects, perfect for dry skin, sunburn, or suntan. The addition of Kojic Acid helps reduces dark spots, giving your skin a clearer, more radiant look. Vitamin E provides natural sun protection while also working as an antioxidant to fight skin damage. Glycerin locks in moisture, leaving your skin soft and smooth. This gel is suitable for all skin types and can be used on your face and body, including sensitive and post-treatment skin, before and after shave care by offering anti-inflammatory and anti-microbial benefits to keep your skin healthy. It’s your go-to solution for achieving a brighter, even-toned skin while keeping it soft, smooth, and hydrated.How to Use : Apply an appropriate amount of Aloe Vera gel to clean and dry skin on your face and body. Gently massage in circular motions until fully absorbed. Use daily for best results to hydrate, brighten, and rejuvenate your skin. Perfect for all skin types.Volume: 200 mL', 'Bio-Xin Cosmeceuticals', 100.0, 1);
