INSERT OR REPLACE INTO marketplace_listings (row_id, channel_name, price, url, matched_title, size, seller, confidence, available) VALUES (35, 'Daraz', 791.0, 'https://www.daraz.com.bd/products/biocare-tea-tree-essential-oil-i1575273216.html', 'BioCare Tea Tree Essential Oil', 'BioCare Tea Tree Essential Oil Reduces acne and pimplesReduces dandruff and scalp flakesProvides natural antibacterial and antifungal protectionProduct Details:BioCare Tea Tree Essential Oil is a premium quality, natural essential oil specially formulated to support acne treatment, oil control, dandruff control, and scalp soothing. Enriched with pure Tea Tree Essential Oil, this fast-absorbing, non-greasy oil helps fight acne-causing bacteria, reduce pimples, control excess sebum, calm skin irritation, and promote a clean, healthy, dandruff-free scalp.Ingredients:Tea Tree Essential Oil – Acts as a natural antibacterial and antifungal agent that helps reduce acne, control excess oil production, relieve dandruff, fight scalp fungus, and soothe irritated skin and itchy scalp.How to Use:1For Skin Care : Mix 2–3 drops of Tea Tree Essential Oil with a carrier oil, moisturizer, or face mask and apply to clean skin.2For Scalp & Dandruff Care : Mix 3–4 drops with a carrier oil and massage gently into the scalp.3For best results, leave on for 1–2 hours or overnight, then wash with shampoo.4Use 2–3 times per week for visible improvement in acne and dandruff control.Volume 10 ml', 'Bio-Xin Cosmeceuticals', 100.0, 1);
