INSERT OR REPLACE INTO marketplace_listings (row_id, channel_name, price, url, matched_title, size, seller, confidence, available) VALUES (37, 'Daraz', 799.0, 'https://www.daraz.com.bd/products/biocare-depigmentation-brightening-essential-oil-i1575250692.html', 'BioCare Depigmentation & Brightening Essential Oil', 'BioCare Depigmentation & Brightening Essential Oil Reduce dark spotsBrightens dull and uneven skin toneDeeply hydrates and softens the skinProduct Details:BioCare Depigmentation & Brightening Essential Oil is a luxurious botanical blend of Sandalwood and Rosehip Essential Oils designed to help improve skin tone and enhance natural radiance. It works to reduce the appearance of dark spots, refine skin texture, soothe irritation, and promote a naturally even and brighter-looking complexion.Ingredients:Sandalwood Oil – Helps calm irritation, refine pores, improve skin clarity, and enhance natural luminosity.Rosehip Oil – Rich in Vitamin A and essential fatty acids, helps fade dark spots, smooth texture, support skin renewal, and boost radiance.How to Use:1For Face Brightening: Mix 2–3 drops with a carrier oil and gently massage onto the face and neck every night to enhance tone and glow.2For Pigmentation Treatment: Apply 3–4 diluted drops directly over dark spots or uneven areas twice daily.3For Bath Therapy: Add 4–5 drops (mixed with a carrier oil) to warm bath water to help refresh and rejuvenate the skin.4For Massage: Blend 5–6 drops with 1 tablespoon of carrier oil and massage gently to nourish the skin and improve overall texture.Volume 10 ml', 'Bio-Xin Cosmeceuticals', 100.0, 1);
