INSERT OR REPLACE INTO marketplace_listings (row_id, channel_name, price, url, matched_title, size, seller, confidence, available) VALUES (44, 'Daraz', 799.0, 'https://www.daraz.com.bd/products/biocare-anti-dandruff-anti-gray-hair-essential-oil-i1575250995.html', 'BioCare Anti-Dandruff & Anti-Gray Hair Essential Oil', 'BioCare Anti-Dandruff & Anti-Gray Hair Essential Oil Control dandruff, flakes, and scalp buildupPrevents premature graying of hairReduce hair fallProduct Details:BioCare Anti-Dandruff & Anti-Gray Hair Essential Oil is a rejuvenating botanical blend designed to purify the scalp by reducing flakes and dandruff, soothing irritation, and supporting natural hair pigment balance.Ingredients:Tea Tree Oil – Purifies the scalp, reduces dandruff flakes, controls excess oil, and helps calm irritation.Polygonum Multiflorum (He Shou Wu) – Helps strengthen hair follicles, supports natural hair pigment balance, slows premature graying, and encourages thicker, healthier-looking hair growth.How to Use:1For Scalp Massage: Mix 3–4 drops with 1 tablespoon of carrier oil. Massage into the scalp and leave for 30 minutes before washing.2For Dandruff Relief: Add 3–4 drops to your regular shampoo or apply diluted directly to the scalp.3For Anti-Gray Hair Care: Apply 2–3 diluted drops to scalp roots and massage gently.4Use 2–3 times per week.Volume 10 ml', 'Bio-Xin Cosmeceuticals', 100.0, 1);
