INSERT OR REPLACE INTO marketplace_listings (row_id, channel_name, price, url, matched_title, size, seller, confidence, available) VALUES (47, 'Daraz', 599.0, 'https://www.daraz.com.bd/products/biocare-baby-face-cream-i1578918717.html', 'BioCare Baby Face Cream', 'BioCare Baby Face Cream Deeply hydrates and keeps baby skin softSoothes sensitive skin and protects from drynessNourishes for healthy, smooth, glowing baby skinProduct DetailsBioCare Baby Face Cream is a gentle, nourishing formula specially developed for delicate baby skin. Enriched with Vitamin E, Rosehip Oil, and Allantoin, it helps keep the skin soft, hydrated, and protected from dryness and environmental stress.This lightweight cream absorbs quickly, providing long-lasting moisture while soothing irritation and maintaining the skin’s natural barrier. Suitable for daily use, it supports healthy, smooth, and supple baby skin.IngredientsVitamin E- Protects baby skin from environmental damage while deeply moisturizing and supporting soft, healthy skinRosehip Oil- Rich in vitamins and fatty acids, it nourishes baby skin, improves texture, and promotes natural skin renewalAllantoin- Gently soothes sensitive baby skin, reduces irritation, and supports smooth, healthy skin repairHow to Use :1Clean your baby’s face gently and pat dry2Take a small amount of cream on your fingertips3Apply evenly on the face4Massage gently in circular motions until absorbed5Use daily, especially after bath or before bedtime Volume :  50 mL', 'Bio-Xin Cosmeceuticals', 100.0, 1);
INSERT OR REPLACE INTO products (row_id, product_name, brand_name, size, manufactured_price, market_average_price, canonical_name) VALUES (48, 'Niacinamide Facial Cleanser 5%', 'Guerniss', '100ml', 348.0, 580.0, 'Guerniss Raw Niacinamide 5% Facial Cleanser 100ml');
INSERT OR REPLACE INTO marketplace_listings (row_id, channel_name, price, url, matched_title, size, seller, confidence, available) VALUES (48, 'Guerniss Official', 580.0, 'https://guerniss.com/products/raw-niacinamide-5-facial-cleanser-100ml', 'Guerniss Raw Niacinamide 5% Facial Cleanser 100ml', 'Guerniss Raw Niacinamide 5% Facial Cleanser 100ml <h3 data-start="402" data-end="435">Full Product Description</h3>
<p data-start="436" data-end="717">Guerniss Raw Niacinamide 5% Facial Cleanser is a gentle yet effective daily face wash formulated to cleanse impurities, brighten skin tone, and maintain hydration. This lightweight, foaming cleanser is suitable for all skin types and helps maintain a healthy, glowing complexion.</p>
<p data-start="719" data-end="1151">Enriched with <strong data-start="733" data-end="751">Niacinamide 5%</strong>, it helps reduce excess oil, minimize pores, and improve skin texture while brightening dull skin. <strong data-start="851" data-end="873">Sodium Hyaluronate</strong> and <strong data-start="878" data-end="890">Glycerin</strong> provide deep hydration, keeping skin soft and supple. Botanical extracts like <strong data-start="969" data-end="994">Aloe Barbadensis Leaf</strong>, <strong data-start="996" data-end="1024">Alaria Esculenta Extract</strong>, and <strong data-start="1030" data-end="1061">Cymbopogon Citratus Extract</strong> soothe and refresh the skin, leaving it calm, smooth, and revitalized after every wash.</p>
<p data-start="1153" data-end="1411">Free from harsh chemicals, this facial cleanser gently removes dirt, oil, and makeup without stripping the skin of its natural moisture. Perfect for daily use, it preps your skin for serums and moisturizers while maintaining a radiant, balanced complexion.</p> 100g 100ml', 'Guerniss', 100.0, 1);
INSERT OR REPLACE INTO marketplace_listings (row_id, channel_name, price, url, matched_title, size, seller, confidence, available) VALUES (48, 'OhSoGo', 490.0, 'https://www.ohsogo.com/products/guerniss-raw-niacinamide-facial-cleanser-5-100ml', 'Guerniss Raw Niacinamide Facial Cleanser 5% (100ml)', 'Guerniss Raw Niacinamide Facial Cleanser 5% (100ml) <h2><br></h2>
