INSERT OR REPLACE INTO marketplace_listings (row_id, channel_name, price, url, matched_title, size, seller, confidence, available) VALUES (109, 'Guerniss Official', 270.0, 'https://guerniss.com/products/xxl-water-proof-mascara', 'Guerniss XXL Water-Proof Mascara', 'Guerniss XXL Water-Proof Mascara <p dir="ltr">Guerniss XXL Waterproof Mascara is a high-performance lash enhancer crafted with a blend of waxes, polymers, and conditioning agents to create bold, full lashes with lasting definition. Its innovative formula resists smudging and flaking, even in the most humid conditions—while nourishing your lashes with every wear.<span></span></p>
<h3 dir="ltr"><span> Why You''ll Love It:</span></h3>
<ul>
<li aria-level="1" dir="ltr">
<p role="presentation" dir="ltr"><span>Intense volume and curl that lasts all day</span><span><br></span></p>
</li>
<li aria-level="1" dir="ltr">
<p role="presentation" dir="ltr"><span>100% waterproof and smudge-proof</span><span><br></span></p>
</li>
<li aria-level="1" dir="ltr">
<p role="presentation" dir="ltr"><span>Lightweight feel, no flaking or clumping</span><span><br></span></p>
</li>
<li aria-level="1" dir="ltr">
<p role="presentation" dir="ltr"><span>Fiber-enhanced for lash extension effect</span><span><br></span></p>
</li>
<li aria-level="1" dir="ltr">
<p role="presentation" dir="ltr"><span>Nourishes lashes with panthenol and wax blends</span></p>
</li>
</ul>
<p dir="ltr">How to use! Watch this </p>
<p dir="ltr">⬇️</p>
<p dir="ltr"><a rel="noopener" href="https://youtube.com/shorts/vLYQVjrLTJg?si=Gpoe8fCAqQostmPz" target="_blank">YOUTUBE VIDEO </a><span></span></p> 10g 10ml', 'Guerniss', 100.0, 1);
