INSERT OR REPLACE INTO marketplace_listings (row_id, channel_name, price, url, matched_title, size, seller, confidence, available) VALUES (110, 'OhSoGo', 710.0, 'https://www.ohsogo.com/products/guerniss-lashfull-mascara-6gm-black', 'Guerniss Lashfull Mascara (6gm) - Black', 'Guerniss Lashfull Mascara (6gm) - Black <style><!--
#html-body [data-pb-style=YERM44H]{justify-content:flex-start;display:flex;flex-direction:column;background-position:left top;background-size:cover;background-repeat:no-repeat;background-attachment:scroll}
--></style>
<div data-content-type="row" data-appearance="contained" data-element="main">
