INSERT OR REPLACE INTO marketplace_listings (row_id, channel_name, price, url, matched_title, size, seller, confidence, available) VALUES (111, 'OhSoGo', 440.0, 'https://www.ohsogo.com/products/guerniss-matte-khol-kajal-3gm-black', 'Guerniss Matte Kohl Kajal (3gm) - Black', 'Guerniss Matte Kohl Kajal (3gm) - Black <p>A long-lasting, jet black matte kohl kajal from Guerniss, formulated with a unique ultra-smooth and creamy formula. Delivers high-intensity color impact that stays put all day without causing harm to the eyes.</p>
<h3>Key Benefits</h3>
<ul>
<li>Jet black, high-intensity color for an instant bold eye look.</li>
<li>Ultra-smooth and creamy formula glides on effortlessly.</li>
<li>Smudge-proof, sweat-proof, and heat-proof for long-lasting wear.</li>
<li>Safe for sensitive eyes, dermatologist and ophthalmologist tested.</li>
<li>Long-lasting formula stays in place without fading or smearing.</li>
<li>Suitable for everyday use and all-day wear.</li>
</ul>
<h3>How to Use</h3>
<ol>
<li>Apply along the upper or lower lash line for a defined look.</li>
<li>Use the tip for a precise, thin line or smudge for a smoky effect.</li>
<li>Layer for a more intense, dramatic look.</li>
<li>Can also be used on the waterline for a bold, wide-eyed effect.</li>
</ol>
<h3>Product Details</h3>
<ul>
<li>
<strong>Brand:</strong> Guerniss</li>
<li>
<strong>Size:</strong> 3g</li>
<li>
<strong>Shade:</strong> Black</li>
<li>
<strong>Finish:</strong> Matte</li>
<li>
<strong>Formula:</strong> Smudge-proof, sweat-proof, heat-proof</li>
<li>
<strong>Tested:</strong> Dermatologist &amp; ophthalmologist tested</li>
<li>
<strong>Suitable For:</strong> All eye types, including sensitive eyes</li>
</ul>
<p>Authentic product at best price in Bangladesh.</p> 300g 300ml', 'Guerniss', 73.78, 1);
