INSERT OR REPLACE INTO marketplace_listings (row_id, channel_name, price, url, matched_title, size, seller, confidence, available) VALUES (113, 'Guerniss Official', 621.0, 'https://guerniss.com/products/eyeink-liquid-eyeliner', 'Guerniss Eyeink Liquid Eyeliner', 'Guerniss Eyeink Liquid Eyeliner <p data-start="0" data-end="173">Guerniss Eyeink Liquid Eyeliner is designed for those who want effortless precision and bold, striking eye looks.<br data-start="113" data-end="116">It lasts all day without compromising comfort or style.</p>
<h2 data-start="175" data-end="502">With its high-definition color payoff, this liquid eyeliner delivers an intense black finish in a single stroke.</h2>
<p data-start="175" data-end="502"><br data-start="287" data-end="290">It is perfect for both everyday wear and dramatic evening styles.<br data-start="355" data-end="358">Whether subtle or bold, this best eyeliner gives full control to express creativity.<br data-start="442" data-end="445">You can easily switch from natural looks to bold wings.</p>
<p data-start="504" data-end="943">The advanced <a href="https://www.instagram.com/reel/DWbWV9REaoS/?utm_source=ig_web_copy_link&amp;igsh=MzRlODBiNWFlZA==" target="_blank" title="" rel="noopener">waterproof eyeliner</a> formula ensures your look stays intact from morning to night.<br data-start="598" data-end="601">It does not smudge, fade, or transfer throughout the day.<br data-start="658" data-end="661">It is crafted with skin-safe polymers for smooth and even application.<br data-start="731" data-end="734">These polymers help the liner stay in place for hours.<br data-start="788" data-end="791">Hydrating agents keep your eyelids comfortable and irritation-free during long wear.<br data-start="875" data-end="878">This makes it suitable for long working days or special events.</p>
<p data-start="945" data-end="1323">One standout feature of this best eyeliner is its precise applicator.<br data-start="1014" data-end="1017">It is designed for accuracy and ease.<br data-start="1054" data-end="1057">It allows you to create clean, sharp lines with minimal effort.<br data-start="1120" data-end="1123">Both beginners and professionals can achieve flawless looks quickly.<br data-start="1191" data-end="1194">You do not need expert skills to get perfect results.<br data-start="1247" data-end="1250">From thin lines to bold styles, the applicator offers full versatility.</p>
<p data-start="1325" data-end="1648">Another reason to love Guerniss Eyeink is its lightweight texture.<br data-start="1407" data-end="1410">This best liquid eyeliner feels barely there on the skin.<br data-start="1467" data-end="1470">It is ideal for all-day use without discomfort.<br data-start="1517" data-end="1520">It suits all skin types, including sensitive eyes.<br data-start="1570" data-end="1573">You can enjoy waterproof eyeliner makeup without irritation or heaviness.</p>
<p data-start="1650" data-end="1956">To get the best results, shake the eyeliner gently before use.<br data-start="1712" data-end="1715">Start from the inner corner and glide along your lash line.<br data-start="1774" data-end="1777">Use light pressure for thin lines and more pressure for bold looks.<br data-start="1844" data-end="1847">Adjust thickness as needed for your desired style.<br data-start="1897" data-end="1900">For a winged look, extend the line outward and upward.</p>
<p data-start="1958" data-end="2171">Pro Tip:<br data-start="1966" data-end="1969">Always store your <a href="https://guerniss.com/products/xxl-water-proof-mascara" target="_blank" title="" rel="noopener">black eyeliner</a> in an upright position.<br data-start="2025" data-end="2028">Keep the cap tightly closed after use.<br data-start="2066" data-end="2069">This prevents drying and maintains consistency.<br data-start="2116" data-end="2119">Proper storage ensures longer-lasting performance.</p>
<p data-start="2173" data-end="2258">Want to see it in action?<br data-start="2198" data-end="2201">Watch the YouTube video below for a step-by-step guide.</p> 5g 5ml', 'Guerniss', 54.16, 1);
INSERT OR REPLACE INTO products (row_id, product_name, brand_name, size, manufactured_price, market_average_price, canonical_name) VALUES (114, 'Guerniss liquid Matte Black Eyeliner', 'Guerniss', '', 468.0, 780.0, 'Semi Matte Black Eyeliner');
INSERT OR REPLACE INTO marketplace_listings (row_id, channel_name, price, url, matched_title, size, seller, confidence, available) VALUES (114, 'Guerniss Official', 780.0, 'https://guerniss.com/products/semi-matte-black-eyeliner', 'Semi Matte Black Eyeliner', 'Semi Matte Black Eyeliner <p><span style="font-weight: 400;">Semi Matte Black Eyeliner comes in a small container with liquid in it and a very thin applicator. It is both matte and waterproof. What we have seen is that matte eyeliners are generally not waterproof. </span></p>
<h4><span style="font-weight: 400;">Eyeliner can be four types. Which are:</span></h4>
<ul>
<li style="font-weight: 400;" aria-level="1"><span style="font-weight: 400;">Gel Eyeliner</span></li>
<li style="font-weight: 400;" aria-level="1"><span style="font-weight: 400;">Liquid Eyeliner</span></li>
<li style="font-weight: 400;" aria-level="1"><span style="font-weight: 400;">Pencil Eyeliner</span></li>
<li style="font-weight: 400;" aria-level="1"><span style="font-weight: 400;">Felt-Tip Eyeliner</span></li>
</ul>
<h1><span style="font-weight: 400;">Guerniss Liquid Matte Black Eyeliner</span></h1>
<p><span style="font-weight: 400;">It is great for those who want to create various types of eyeliner looks, for example cat eye, foxy eye etc. It is very easy to grip and apply. It is a 5ml product that is very lightweight and handy. </span></p>
<p><span style="font-weight: 400;">The applicator is very thin and precise so you can make any look with this eyeliner easily.</span></p>
<p><span style="font-weight: 400;">This eyeliner is smudge proof which is perfect for oily upper lids. It is waterproof so it does not wash away with sweat or rain. It is very long lasting and doesn’t crack or fades away.</span></p>
<p><span style="font-weight: 400;">The colour is intense matte black that can create a dramatic finish to your eyelook and over all makeup look. A good makeup look is highly dependent on good waterproof eyeliner. Sometimes we do not use anything else apart from eyeliner in our everyday look. So it is very important to use high quality eyeliner.</span></p>
<h2><b>About Eye health </b></h2>
<p><span style="font-weight: 400;">Eye is the most sensitive organ of our body. The skin of the eye area is thin and it can get affected easily by harmful chemicals. A good quality eyeliner is very important for your eye health. This eyeliner is absolutely safe for sensitive eyes.</span></p>
<h2><span style="font-weight: 400;">More about Liquid Matte Black Eyeliner </span></h2>
<p><span style="font-weight: 400;">This product is a perfect eyeliner for your everyday use. And also great for occasional wear. Besides, this product is affordable, cruelty free and vegan. The coverage is buildable with intense jet black colour so that you can make your look more alluring and attractive.</span></p>
<p><span style="font-weight: 400;"> </span></p>', 'Guerniss', 73.78, 0);
INSERT OR REPLACE INTO products (row_id, product_name, brand_name, size, manufactured_price, market_average_price, canonical_name) VALUES (115, 'Makeup Setting Spray', 'Guerniss', '100 ml', 714.0, 1190.0, 'Matte Makeup Setting Spray');
INSERT OR REPLACE INTO marketplace_listings (row_id, channel_name, price, url, matched_title, size, seller, confidence, available) VALUES (115, 'Guerniss Official', 1190.0, 'https://guerniss.com/products/matte-makeup-setting-spray', 'Matte Makeup Setting Spray', 'Matte Makeup Setting Spray <p><span style="font-weight: 400;">Matte Makeup</span> <span style="font-weight: 400;">Setting spray is a cosmetic product that is designed to preserve applied make-up in place and gives longevity. A </span><span style="font-weight: 400;">setting spray also gives a smooth, non-powdery, non-cakey, and nourished look to the skin. </span></p>
<p><span style="font-weight: 400;">We usually apply setting spray at the end of the makeup procedure. The overall purpose of using a matte makeup setting spray is to help prevent the makeup from sliding, smudging, creasing, or fading quickly.</span></p>
<h1><span style="font-weight: 400;">Types of Setting Sprays:</span></h1>
<ul>
<li style="font-weight: 400;" aria-level="1"><span style="font-weight: 400;">Mattifying Setting Spray</span></li>
<li style="font-weight: 400;" aria-level="1"><span style="font-weight: 400;">Illuminating Setting Spray</span></li>
</ul>
<p><span style="font-weight: 400;">Many companies make some setting sprays infused with soothing, hydrating and calming ingredients. </span></p>
<p><span style="font-weight: 400;">Makeup artists and experts recommend using Guerniss matte makeup setting spray over the skin post makeup application. But if it''s a big night or even a wedding and you''re looking for a super sturdy base. A pump between each makeup step will help to lock the makeup in.</span></p>
<h2><span style="font-weight: 400;">How to use the product</span></h2>
<p><span style="font-weight: 400;">You should hold the bottle six to eight inches away from your face. Some people spray it very close to the face as a result the spray doesn''t spread evenly on the face. Spray the matte makeup setting spray a few times, make sure you get full, even coverage on your face. Use setting spray on the top layer of makeup for best results. After setting all the products.</span></p>
<h3><span style="font-weight: 400;">More about Makeup Setting Spray</span></h3>
<p><span style="font-weight: 400;">We formulate this product and develop to hold your full face makeup solidly in place as a top coat after you have completed all your makeup steps.. If you have oily skin or your makeup gradually smudges and gradually fades away, guerniss makeup setting spray could be the best possible solution for you. </span></p>
<p><span style="font-weight: 400;">Since matte makeup setting spray application is in the final step of your makeup, it never comes in contact with your actual skin. So,for your hypersensitive skin our setting spray should be your ideal choice.</span></p>
<p><span style="font-weight: 400;"> Consequently it keeps your skin matte and hydrated, intensifies your foundation finish and prolongs your makeup staying power</span></p>
<p> </p> 100g 100ml', 'Guerniss', 100.0, 0);
