INSERT OR REPLACE INTO marketplace_listings (row_id, channel_name, price, url, matched_title, size, seller, confidence, available) VALUES (168, 'OhSoGo', 199.0, 'https://www.ohsogo.com/products/nature-beauty-tea-tree-cleansing-face-wash-100ml', 'Nature Beauty Tea Tree Cleansing Face Wash (100ml)', 'Nature Beauty Tea Tree Cleansing Face Wash (100ml) <style type="text/css"><!--td {border: 1px solid #cccccc;}br {mso-data-placement:same-cell;}--></style>
<p>Nature Beauty Tea Tree Facewash enriched with the natural essence of tea tree, provides deep cleansing. Regular use helps to reduce pimples, controls excess oil, and leaves you with a healthy, balanced complexion.</p>
<p><strong>Key Features</strong></p>
<p>&gt; Reduces acne<br>&gt; Controls excess sebum production<br>&gt; Moisturizes skin<br>&gt; Makes skin bright<br>&gt; Maintains pH level of skin<br>&gt; Gel Based</p>
<p><strong>Ingredient</strong></p>
<p>Aqua, Hydroxypropyl Ethylcellulose, PEG-40, Sodium Laureth Sulfate, Sodium Lauryl Sulfate, Tea Tree Oil, Soda Ash, Glycerin, Propylene Glycol, Vitamin E, Polyquaternium-7, Polyquaternium-10, Niacinamide, Disodium EDTA, Panthenol, Phenoxyethanol, DMDM Hydantoin, Triclosan, Color,Flavor.etc.</p>
<p><strong>How To Use</strong></p>
<p>Squeeze a small amount onto your fingertips and gently rub your palms together to create foam. Apply it on damp face and massage in circular motions. Rinse thoroughly with water. After cleansing, apply a toner and moisturizer. Before first use, it is highly recommended to do a patch test on a small area of skin to check for any reactions.</p>', 'Nature Beauty', 71.9, 0);
