INSERT OR REPLACE INTO marketplace_listings (row_id, channel_name, price, url, matched_title, size, seller, confidence, available) VALUES (174, 'OhSoGo', 220.0, 'https://www.ohsogo.com/products/nature-beauty-appricot-face-scrub-130ml', 'Nature Beauty Appricot Face Scrub (130ml)', 'Nature Beauty Appricot Face Scrub (130ml) <style type="text/css"><!--td {border: 1px solid #cccccc;}br {mso-data-placement:same-cell;}--></style>
<p><span data-sheets-root="1">Nature Beauty Apricot Face Scrub gently exfoliates the skin, removing dead cells and impurities for a brighter-looking skin. Rich in vitamins A and C, it nourishes and revitalises, promoting a healthy glow. Its natural ingredients help to improve skin texture and unclog pores. Regular use can lead to smoother, softer skin and a more even tone.</span></p>
<p><strong>Key Features</strong></p>
<p>&gt; Exfoliates and Removes Impurities<br>&gt; Nourishes and Revitalizes<br>&gt; Improves Skin Texture and Unclogs Pores<br>&gt; Promotes Smoother, Softer Skin and Even Tone</p>
<p><strong>How To Use</strong><br>Wash your face with facewash. On slightly damp skin, take a small amount of scrub using a clean spatula or your fingers and gently massage in circular motions, avoiding the area around the eyes, for 30-45 seconds. Then rinse off with water. Use toner and moisturiser according to your skin’s needs. Use 1-2 times a week.<br>Before first use, it is highly recommended to do a patch test on a small area of skin to check for any reactions.<br></p>
