INSERT OR REPLACE INTO marketplace_listings (row_id, channel_name, price, url, matched_title, size, seller, confidence, available) VALUES (176, 'OhSoGo', 440.0, 'https://www.ohsogo.com/products/nature-beauty-sunscreen-gentle-cream-spf-50-pa-50ml', 'Nature Beauty Sunscreen Gentle Cream SPF 50 PA+++ (50ml)', 'Nature Beauty Sunscreen Gentle Cream SPF 50 PA+++ (50ml) <style type="text/css"><!--td {border: 1px solid #cccccc;}br {mso-data-placement:same-cell;}--></style>
<p><span data-sheets-root="1">Nature Beauty Sunscreen Cream offers effective UV protection from harmful rays, keeps skin hydrated, and has a lightweight formula that absorbs quickly and gently on all skin types, helping to prevent premature ageing for a healthy, youthful appearance.<br><br></span></p>
<p><strong>Ingredient</strong></p>
<p>Aqua, Carbopol, Triclosan, Butylated Hydroxytoluene (BHT), Triethanolamine, Glyceryl Monostearate, Emulsifying Wax, Palmitic Acid, Glycerin, Propylene Glycol, Coconut Oil, Titanium Dioxide, Dimethicone, Niacinamide, Panthenol, Biotin, Ethylhexyl Methoxycinnamate, Avobenzone, Benzophenone-3, Tocopheryl Acetate, Allantoin, Polyquaternium-10, Phenoxyethanol, DMDM Hydantoin, EDTA, Sodium, Benzoate, Potassium Sorbate, Color, Flavour, etc.</p>
<p><strong>How To Use</strong></p>
<p>Apply an adequate amount of sunscreen 15-20 minutes before sun exposure to all exposed areas of your skin. Don’t forget to reapply every 2 hours, or more frequently if you’re swimming or sweating. Before first use, it is highly recommended to do a patch test on a small area of skin to check for any reactions.</p>
<p><span data-sheets-root="1"><br></span></p>', 'Nature Beauty', 100.0, 1);
